// Le garage de l'ultra (planche « Ultra · garage, départ, chrono », validée par Fi le 18 octobre) :
// le vélo sur le pied d'atelier, l'équipement accroché au panneau ; la monnaie, c'est le poids.
import {ULTRA_BIKES,ULTRA_GEAR,ULTRA_WEIGHT,ultraKit,ultraKg,ultraLoad} from './ultra.js';
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const BIKE_SVG=`<svg class="ug-bike" viewBox="0 0 520 300" aria-label="Le vélo sur le pied d'atelier"> <rect x="0" y="262" width="520" height="38" fill="#0f2023"/> <path d="M250 262 L262 196 L274 262" stroke="#4d6b66" stroke-width="7" fill="none" stroke-linecap="round"/> <g class="ug-eq" data-g="camel"><path d="M448 40 v18" stroke="#9fb3ae" stroke-width="3"/><rect x="430" y="58" width="38" height="58" rx="12" fill="#2e5d7a" stroke="#1b1406" stroke-width="3"/><rect x="438" y="68" width="22" height="34" rx="8" fill="#6fa8c9" stroke="#1b1406" stroke-width="2"/><path d="M449 116 q8 22 -6 34" stroke="#1b1406" stroke-width="3" fill="none"/><text x="449" y="172" fill="#f6e7c1" font-family="Barlow Condensed" font-size="13" text-anchor="middle">2 L d’eau</text></g> <g> <circle class="ug-w" cx="140" cy="205" r="58" fill="none" stroke="#1b1406" stroke-width="9"/> <circle class="ug-w" cx="380" cy="205" r="58" fill="none" stroke="#1b1406" stroke-width="9"/> <circle cx="140" cy="205" r="52" fill="none" stroke="#9fb3ae" stroke-width="1" stroke-dasharray="2 9"/> <circle cx="380" cy="205" r="52" fill="none" stroke="#9fb3ae" stroke-width="1" stroke-dasharray="2 9"/> <circle cx="140" cy="205" r="6" fill="#f6e7c1" stroke="#1b1406" stroke-width="2"/> </g> <g class="ug-mt" data-mt="route"><path d="M140 205 L240 205 L210 110 Z M240 205 L355 112 L210 110 M355 112 L380 205" stroke="#c8483a" stroke-width="8" fill="none" stroke-linejoin="round"/><path d="M355 112 L350 92 L378 88 q18 6 6 26" stroke="#1b1406" stroke-width="5" fill="none"/><path d="M210 110 L204 86 M186 84 h38" stroke="#1b1406" stroke-width="6" stroke-linecap="round"/></g> <g class="ug-mt" data-mt="gravel"><path d="M140 205 L240 205 L212 112 Z M240 205 L352 116 L212 112 M352 116 L380 205" stroke="#f2a541" stroke-width="9" fill="none" stroke-linejoin="round"/><path d="M352 116 L346 92 L376 88 q18 8 4 28" stroke="#1b1406" stroke-width="5" fill="none"/><path d="M212 112 L206 86 M188 84 h38" stroke="#1b1406" stroke-width="6" stroke-linecap="round"/></g> <g class="ug-mt" data-mt="vtt"><path d="M140 205 L240 205 L208 122 Z M240 205 L346 108 L208 122" stroke="#7fb28a" stroke-width="10" fill="none" stroke-linejoin="round"/><path d="M346 108 L366 160" stroke="#1b1406" stroke-width="9"/><path d="M366 160 L380 205" stroke="#c9c9b0" stroke-width="7"/><path d="M346 108 L342 86 M322 84 h44" stroke="#1b1406" stroke-width="6" stroke-linecap="round"/><path d="M208 122 L202 92 M184 90 h38" stroke="#1b1406" stroke-width="6" stroke-linecap="round"/></g> <g class="ug-eq" data-g="aero"><path d="M350 90 L420 82" stroke="#1b1406" stroke-width="5" stroke-linecap="round"/><path d="M352 98 L422 90" stroke="#1b1406" stroke-width="5" stroke-linecap="round"/><rect x="352" y="76" width="20" height="9" rx="4" fill="#f6e7c1" stroke="#1b1406" stroke-width="2"/><rect x="352" y="96" width="20" height="9" rx="4" fill="#f6e7c1" stroke="#1b1406" stroke-width="2"/></g> <g class="ug-eq" data-g="dynamo"><circle cx="380" cy="205" r="12" fill="#f2a541" stroke="#1b1406" stroke-width="3"/><path d="M380 205 L366 120" stroke="#1b1406" stroke-width="2" stroke-dasharray="3 3"/><rect x="356" y="112" width="22" height="14" rx="4" fill="#f6e7c1" stroke="#1b1406" stroke-width="3"/><path d="M380 116 L470 96 L470 140 Z" fill="#f6e7c155"/></g> <g class="ug-eq" data-g="tige"><rect x="196" y="88" width="14" height="22" rx="3" fill="#7fb28a" stroke="#1b1406" stroke-width="2"/><path d="M198 92 h10 M198 98 h10 M198 104 h10" stroke="#1b1406" stroke-width="2"/></g> <g class="ug-eq" data-g="fourche"><path d="M356 120 L374 196" stroke="#c9c9b0" stroke-width="11" stroke-linecap="round"/><path d="M356 120 L364 154" stroke="#1b1406" stroke-width="12" stroke-linecap="round"/></g> <g class="ug-eq" data-g="bivy"><rect x="300" y="62" width="44" height="24" rx="12" fill="#6b7f3a" stroke="#1b1406" stroke-width="3" transform="rotate(-6 322 74)"/><path d="M312 64 v22 M332 62 v22" stroke="#1b1406" stroke-width="2"/></g> <g class="ug-eq" data-g="gps"><rect x="262" y="104" width="34" height="14" rx="4" fill="#21454a" stroke="#1b1406" stroke-width="3"/><path d="M270 111 h8 l-3 -4 M286 108 v6" stroke="#f2a541" stroke-width="2"/></g> <g class="ug-eq" data-g="tubeless"><circle cx="140" cy="205" r="58" fill="none" stroke="#7fb28a" stroke-width="3"/><circle cx="380" cy="205" r="58" fill="none" stroke="#7fb28a" stroke-width="3"/><text x="140" y="138" fill="#7fb28a" font-family="Barlow Condensed" font-size="13" text-anchor="middle">tubeless</text></g> <g class="ug-eq" data-g="couverture"><path d="M60 40 h50 l-6 30 h-38 z" fill="#d8c060" stroke="#1b1406" stroke-width="3"/><path d="M85 22 v18" stroke="#9fb3ae" stroke-width="3"/><text x="85" y="88" fill="#f6e7c1" font-family="Barlow Condensed" font-size="13" text-anchor="middle">couverture</text></g> <path d="M222 120 L236 196 L332 122 Z" fill="#2e4d4a" stroke="#1b1406" stroke-width="3" opacity=".9"/> <path d="M196 100 q-50 2 -64 22 q30 12 70 -6 z" fill="#2e4d4a" stroke="#1b1406" stroke-width="3"/> </svg>`;
const fmt=kg=>String(Math.round(kg*10)/10).replace('.',',');
function bikeArt(kit){const b=ULTRA_BIKES[kit.bike];let s=BIKE_SVG.replace(/class="ug-mt" data-mt="(\w+)"/g,(x,id)=>`class="ug-mt${id===kit.bike?' on':''}" data-mt="${id}"`)
 .replace(/class="ug-eq" data-g="(\w+)"/g,(x,id)=>`class="ug-eq${kit.gear.includes(id)||(id==='fourche'&&b.fork)?' on':''}" data-g="${id}"`);
 const w=kit.bike==='route'?6:kit.bike==='vtt'?12:9;return s.replace(/class="ug-w" cx="(\d+)" cy="205" r="58" fill="none" stroke="#1b1406" stroke-width="9"/g,(x,cx)=>`class="ug-w" cx="${cx}" cy="205" r="58" fill="none" stroke="#1b1406" stroke-width="${w}"`);}
export function ultraGarageScreen({btn,steps,player,index,total}){
 const kit=ultraKit(player.ultraBike,player.ultraGear),kg=ultraKg(kit.bike,kit.gear),load=ultraLoad(kg),b=ULTRA_BIKES[kit.bike];
 const pct=Math.max(4,Math.min(100,(kg-12)/(21-12)*100));
 const mounts=Object.entries(ULTRA_BIKES).map(([id,x])=>`<button class="ug-mount${id===kit.bike?' on':''}" data-ultra-bike="${id}" aria-pressed="${id===kit.bike}"><b>${esc(x.name)}</b><span>${fmt(x.kg)} kg · ${esc(x.tag)}</span><small>${esc(x.line)}</small></button>`).join('');
 const peg=Object.entries(ULTRA_GEAR).map(([id,g])=>{const blocked=(g.not||[]).includes(kit.bike),on=kit.gear.includes(id)||(id==='fourche'&&b.fork);
  return `<button class="ug-item${on?' on':''}" data-ultra-gear="${id}" aria-pressed="${on}" ${blocked?'disabled':''}><b>${esc(g.name)}</b><span>${esc(g.text)}</span><em>${fmt(g.kg)} kg${blocked&&b.fork&&id==='fourche'?' · déjà montée':blocked?' · pas sur ce vélo':''}</em></button>`;}).join('');
 const fx=[`<li>${esc(b.line)}</li>`,...kit.gear.map(id=>`<li>${esc(ULTRA_GEAR[id].name)} : ${esc(ULTRA_GEAR[id].text)}</li>`),`<li class="${load.id==='leger'?'':'minus'}">${esc(load.name)} (${fmt(kg)} kg) : ${esc(load.text)}</li>`].join('');
 return `<main class="menu-c mc-page mc-garage ug-page">${steps('gear')}
  <header class="mc-head"><div><p class="mc-kicker">Le garage de l’ultra · ${index+1}/${total}</p><h1>${esc(player.name)}, prépare ta machine</h1><p class="mc-lead">Pas d’argent en course : ce qui compte, c’est le poids. Clique une pièce pour la monter sur le vélo.</p></div>${btn('← Cyclistes','setup','mc-ghost')}</header>
  <div class="ug-mounts" role="group" aria-label="Monture">${mounts}</div>
  <div class="ug-grid">
   <section class="ug-atelier" aria-label="Le vélo sur le pied d’atelier">${bikeArt(kit)}
    <div class="ug-scale"><div class="ug-scale-top"><span>Poids chargé</span><b>${fmt(kg)} kg</b><em class="${load.id}">${esc(load.name)}</em></div>
     <div class="ug-bar"><i style="width:${pct}%"></i><s style="left:${(ULTRA_WEIGHT.light-12)/9*100}%"></s><s style="left:${(ULTRA_WEIGHT.heavy-12)/9*100}%"></s></div>
     <div class="ug-scale-lab"><span>12 kg</span><span>${ULTRA_WEIGHT.light} kg : cols +1 h</span><span>${ULTRA_WEIGHT.heavy} kg : montagne aussi</span><span>21</span></div></div>
   </section>
   <section class="ug-side"><div class="ug-peg" role="group" aria-label="Équipement">${peg}</div>
    <div class="ug-sum"><h3>${esc(b.name)}</h3><ul>${fx}</ul></div></section>
  </div>
  <footer class="mc-foot">${btn('← Cyclistes','setup','mc-ghost')}<span></span>${btn('Vers la ligne de départ →','equipment-next','mc-go')}</footer>
 </main>`;}
